/**
 * bos-nepali-date — Client-side search
 * Zero dependencies. Fetches search-index.json auto-generated by scripts/build-search-index.js.
 * Run `npm run docs:build-index` after editing docs to regenerate.
 */

(function() {
  'use strict';

  var data = [];
  var dataLoaded = false;
  var loadingQueue = [];
  var isOpen = false;
  var selectedIdx = -1;
  var results = [];

  // ── DOM refs ──
  var overlay, input, list;

  function createUI() {
    var html = '' +
      '<div id="search-overlay" role="dialog" aria-modal="true" aria-label="Search docs" style="display:none;position:fixed;inset:0;z-index:9999;background:oklch(0 0 0 / 0.3);-webkit-backdrop-filter:blur(2px);backdrop-filter:blur(2px)">' +
        '<div style="max-width:600px;margin:80px auto 0;padding:0 16px">' +
          '<div style="background:oklch(1 0 0);border-radius:12px;box-shadow:0 8px 40px oklch(0 0 0 / 0.15);overflow:hidden">' +
            '<div style="display:flex;align-items:center;border-bottom:1px solid oklch(0.91 0.006 262);padding:0 16px">' +
              '<span style="font-size:16px;color:oklch(0.42 0.018 262);margin-right:10px">🔍</span>' +
              '<input id="search-input" type="text" placeholder="Search docs…" autocomplete="off" spellcheck="false" style="flex:1;border:none;outline:none;padding:14px 0;font-size:15px;font-family:inherit;color:oklch(0.13 0.012 262);background:transparent;width:100%">' +
              '<kbd style="font-size:11px;padding:2px 7px;border-radius:4px;border:1px solid oklch(0.91 0.006 262);color:oklch(0.42 0.018 262);font-family:inherit;background:oklch(0.965 0.004 262)">Esc</kbd>' +
            '</div>' +
            '<div id="search-results" style="max-height:400px;overflow-y:auto"></div>' +
            '<div id="search-empty" style="display:none;padding:24px;text-align:center;font-size:14px;color:oklch(0.42 0.018 262)">No results found.</div>' +
          '</div>' +
        '</div>' +
      '</div>';
    document.body.insertAdjacentHTML('beforeend', html);
    overlay = document.getElementById('search-overlay');
    input = document.getElementById('search-input');
    list = document.getElementById('search-results');
    var empty = document.getElementById('search-empty');

    // Events
    var btn = document.getElementById('search-btn');
    if (btn) btn.addEventListener('click', open);
    input.addEventListener('input', onInput);
    input.addEventListener('keydown', onKey);
    overlay.addEventListener('click', function(e) {
      if (e.target === overlay) close();
    });
    document.addEventListener('keydown', function(e) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); toggle(); }
      if (e.key === 'Escape' && isOpen) { e.preventDefault(); close(); }
      if (e.key === '/' && !isOpen && !e.target.matches('input,textarea,select,[contenteditable]')) { e.preventDefault(); open(); }
    });
  }

  function loadData(callback) {
    if (dataLoaded) { if (callback) callback(); return; }
    var xhr = new XMLHttpRequest();
    xhr.open('GET', '/search-index.json', true);
    xhr.onload = function() {
      if (xhr.status === 200) {
        try { data = JSON.parse(xhr.responseText); } catch(e) { data = []; }
        dataLoaded = true;
        // Process queued queries
        for (var i = 0; i < loadingQueue.length; i++) loadingQueue[i]();
        loadingQueue = [];
      }
      if (callback) callback();
    };
    xhr.onerror = function() { if (callback) callback(); };
    xhr.send();
  }

  function toggle() { isOpen ? close() : open(); }

  function open() {
    loadData(); // ensure data is loaded on first open
    isOpen = true;
    overlay.style.display = '';
    document.body.style.overflow = 'hidden';
    setTimeout(function() { input.focus(); }, 50);
  }

  function close() {
    isOpen = false;
    overlay.style.display = 'none';
    document.body.style.overflow = '';
    input.value = '';
    list.innerHTML = '';
    document.getElementById('search-empty').style.display = 'none';
    results = [];
    selectedIdx = -1;
  }

  function doSearch() {
    var q = input.value.trim().toLowerCase();
    if (!q) { list.innerHTML = ''; document.getElementById('search-empty').style.display = 'none'; results = []; selectedIdx = -1; return; }

    var terms = q.split(/\s+/).filter(Boolean);
    var scored = [];

    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      var haystack = (item.t + ' ' + item.c).toLowerCase();
      var score = 0;
      var allMatch = true;
      for (var t = 0; t < terms.length; t++) {
        var term = terms[t];
        var idx = haystack.indexOf(term);
        if (idx === -1) { allMatch = false; break; }
        // Title match scores higher
        if (item.t.toLowerCase().indexOf(term) !== -1) score += 10;
        // Early position in content scores higher
        score += Math.max(0, 20 - idx / 10);
      }
      if (allMatch) {
        // Boost shorter results (denser matches)
        score += Math.max(0, 10 - item.c.length / 200);
        scored.push({ index: i, score: score });
      }
    }

    scored.sort(function(a, b) { return b.score - a.score; });
    var top = scored.slice(0, 8);
    results = top.map(function(s) { return data[s.index]; });
    selectedIdx = -1;
    renderResults(q);
  }

  function onInput() {
    if (!dataLoaded) {
      loadingQueue.push(function() {
        if (document.getElementById('search-overlay') && document.getElementById('search-overlay').style.display !== 'none') {
          doSearch();
        }
      });
      return;
    }
    doSearch();
  }

  function renderResults(q) {
    var empty = document.getElementById('search-empty');
    if (!results.length) {
      list.innerHTML = '';
      empty.style.display = '';
      return;
    }
    empty.style.display = 'none';

    var terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    var html = '';
    for (var i = 0; i < results.length; i++) {
      var r = results[i];
      var isSel = i === selectedIdx;
      var titleHtml = highlight(r.t, terms);
      var pageHtml = r.p;
      var snippet = r.c.length > 120 ? r.c.substring(0, 120) + '…' : r.c;
      snippet = highlight(snippet, terms);

      html += '' +
        '<a href="' + r.u + '" class="sr-item" data-idx="' + i + '" style="display:block;padding:10px 16px;text-decoration:none;border-bottom:1px solid oklch(0.94 0.004 262);transition:background 0.1s;' + (isSel ? 'background:oklch(0.935 0.02 262);' : '') + '">' +
          '<div style="font-size:14px;font-weight:600;color:oklch(0.13 0.012 262);margin-bottom:2px">' + titleHtml + '</div>' +
          '<div style="font-size:12px;color:oklch(0.62 0.16 262);margin-bottom:4px">' + pageHtml + '</div>' +
          '<div style="font-size:13px;color:oklch(0.42 0.018 262);line-height:1.4">' + snippet + '</div>' +
        '</a>';
    }
    list.innerHTML = html;

    // Attach click handlers
    var items = list.querySelectorAll('.sr-item');
    for (var j = 0; j < items.length; j++) {
      (function(el) {
        el.addEventListener('click', function(e) {
          e.preventDefault();
          window.location.href = el.getAttribute('href');
          close();
        });
      })(items[j]);
    }
  }

  function highlight(text, terms) {
    var t = text;
    for (var i = 0; i < terms.length; i++) {
      var term = terms[i];
      var idx = t.toLowerCase().indexOf(term);
      if (idx !== -1) {
        var before = t.substring(0, idx);
        var match = t.substring(idx, idx + term.length);
        var after = t.substring(idx + term.length);
        t = before + '<strong style="font-weight:600;color:oklch(0.52 0.19 262);background:oklch(0.93 0.04 262);border-radius:2px;padding:0 2px">' + match + '</strong>' + after;
      }
    }
    return t;
  }

  function onKey(e) {
    var items = list.querySelectorAll('.sr-item');
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      selectedIdx = Math.min(selectedIdx + 1, results.length - 1);
      updateSelection();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      selectedIdx = Math.max(selectedIdx - 1, 0);
      updateSelection();
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (selectedIdx >= 0 && selectedIdx < results.length) {
        window.location.href = results[selectedIdx].u;
        close();
      }
    }
  }

  function updateSelection() {
    var items = list.querySelectorAll('.sr-item');
    for (var i = 0; i < items.length; i++) {
      items[i].style.background = i === selectedIdx ? 'oklch(0.935 0.02 262)' : '';
    }
    if (selectedIdx >= 0 && items[selectedIdx]) {
      items[selectedIdx].scrollIntoView({ block: 'nearest' });
    }
  }

  // Init on DOM ready: load data first, then create UI
  function init() {
    createUI();
    loadData();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
